# ─────────────────────────────────────────────────────────────────────────────
#  FIG 2: Continuous Feature Distributions by Class
# ─────────────────────────────────────────────────────────────────────────────
cont_cols = [c for c in CONTINUOUS_FEATURES if c in df_train.columns]
n_cont = len(cont_cols)

fig, axes = plt.subplots(2, n_cont, figsize=(4*n_cont, 8))
