sens = tp/(tp+fn) if (tp+fn)>0 else 0
spec_val = tn/(tn+fp) if (tn+fp)>0 else 0
ax5.set_title(f'Ensemble Confusion Matrix (Test)\n'
              f'Sens={sens:.3f}  Spec={spec_val:.3f}  F1={ENS_TEST_RESULT["f1"]:.3f}',
              fontsize=10, fontweight='bold')

