fig.suptitle('Fig 22 — Cross-Validation Stability: AUC & F1 Distribution '
             '(All Models + Ensemble)', fontsize=14, fontweight='bold')

auc_data = [ALL_MODELS_CV[n]['roc_auc'].values for n in MODEL_ORDER]
