axes[1].legend(fontsize=8)
for i, (mn, mx) in enumerate(zip(sorted_means, sorted_maxs)):
    axes[1].text(mn + 0.003, i, f'{mn:.3f}', va='center', fontsize=8)

plt.tight_layout()
